}

mutation acceptInvite($hash: String!, $firstName: String, $lastName: String, $phoneNumber: String, $gender: GenderEnum, $address: String, $birthDay: Date) {
  acceptInvite(
    hash: $hash
    firstName: $firstName
    lastName: $lastName
    phoneNumber: $phoneNumber
    gender: $gender
    address: $address
    birthDay: $birthDay
  ) {
    ...AuthenticationResult
  }
}

fragment AuthenticationResult on AuthenticationResult {
  ... on AuthPayload {
    ...AuthPayload
  }
  ... on OnboardingResponseType {
    ...OnboardingResponseType
  }
  ... on OnetimePasswordResponseType {
    ...OnetimePasswordResponseType
  }
}

fragment AuthPayload on AuthPayload {
