query adminsLookup($userIds: [String!], $searchString: String, $roles: [MemberRole], $orgContext: OrgContextInput!, $pagination: PaginationType!) {
  membersLookup(
    userIds: $userIds
    searchString: $searchString
    roles: $roles
    orgContext: $orgContext
    pagination: $pagination
  ) {
    page {
      ...MemberInfoFragment
      facets(roles: $roles, orgContext: $orgContext) {
        ... on DivisionAdminMemberFacet {
          division {
            id
            name
            club {
              id
              name
            }
          }
          role
        }
        ... on ClubAdminMemberFacet {
          club {
            id
            name
          }
          role
        }
        ... on SuperAdminFacetType {
          role
        }
      }
    }
    pageInfo {
      hasNextPage
      hasNextPage
      startCursor
      endCursor
    }
  }
}

