query ageGroup($id: String) {
  ageGroup(id: $id) {
    edges {
      node {
        id
        orgId
        name
        createdAt
        ageStart
        ageEnd
        periodStart
        periodEnd
        picture
        coachCount
        memberVisibility
        coachCountAblerUser
        settings
        guardiansDisabled
        gender
        playerCount
        playerWithoutGuardianCount
        wallDisabled
        playerWithoutGuardian(first: 30) {
          edges {
            node {
              id
              displayName
            }
          }
        }
        players {
          edges {
            node {
              id
              displayName
              ablerUser
            }
          }
        }
        playerCountAblerUser
        guardianCount
        groups {
          id
          name
          default
          label
          coachCount
          playerCount
          coaches {
            ...CoachesOf
          }
        }
        resources {
          id
          name
          label
          capacity
          tournamentProviders {
            providerKey
            externalId
          }
          locationLink
          locationAddress
        }
        sport {
          id
          name
          sportType
          options
        }
        tournamentProviders {
          providerKey
          externalId
          divisionOverrideId
        }
        organization {
          id
          clubId
          name
          advaniaOrgNumber
          sportTypes
          country
          wallDisabled
          tournamentProviders {
            providerId
            providerKey
            externalId
          }
          club {
            id
            name
            label
            options
            wallDisabled
            country
            currencyCode
            timezone
          }
        }
        coaches {
          ...CoachesOf
        }
      }
    }
  }
}

