query scheduleV2($filter: scheduleV2Filter, $exclude: EventExcludeInputFilter, $roles: [EventParticipantRole!]!, $segment: EventParticipantsSegment!, $skipParticipation: Boolean!, $pagination: PaginationType!) {
  scheduleV2(filter: $filter, exclude: $exclude, pagination: $pagination) {
    page {
      ... on GenericEvent {
        id
