        type
        from
        to
        registrationEnd
        attachments {
          id
        }
        eventPlayerStats {
          presentCount
          absentCount
          goingCount
          notGoingCount
          maybeCount
          notRespondedCount
        }
        attendanceLimit
        arrivalTime
        paymentRequestInfo
        pinUntilRespond
        locationLink
        locationAddress
        locationDetails
        ageGroup {
          id
          orgId
          name
          guardiansDisabled
        }
        participation(segment: $segment, roles: $roles) @skip(if: $skipParticipation) {
          ... on EventPlayer {
            id
            status
            coachStatus
            paymentStatus
            orderId
            player {
              id
              lastName
              firstName
              displayName
              initials
              picture
              ablerUser
            }
          }
          ... on EventCoach {
            id
            role
            user {
              id
              initials
              picture
              displayName
            }
            attendance {
              status
              statusUpdatedBy {
                id
                initials
                displayName
              }
              statusExt
            }
          }
        }
      }
      ... on MatchEvent {
        id
        name
        type
        from
        to
        registrationEnd
        attachments {
          id
        }
        eventPlayerStats {
          presentCount
          absentCount
          goingCount
          notGoingCount
          maybeCount
          notRespondedCount
        }
        attendanceLimit
        arrivalTime
        paymentRequestInfo
        pinUntilRespond
        locationLink
        locationAddress
        locationDetails
        ageGroup {
          id
          orgId
          name
          guardiansDisabled
          organization {
            id
            name
            sportTypes
          }
        }
        participation(segment: $segment, roles: $roles) @skip(if: $skipParticipation) {
          ... on EventPlayer {
            id
            status
            coachStatus
            paymentStatus
            orderId
            player {
              id
              lastName
              firstName
              displayName
              initials
              picture
              ablerUser
            }
          }
          ... on EventCoach {
            id
            role
            user {
              id
              initials
              picture
              displayName
            }
            attendance {
              status
              statusUpdatedBy {
                id
                initials
                displayName
              }
              statusExt
            }
          }
        }
        result
        homeAway
        advaniaGameId
        tournamentProviders {
          providerKey
          externalId
        }
      }
    }
    pageInfo {
      hasPreviousPage
      hasNextPage
      startCursor
      endCursor
    }
  }
}

